        assert(bag_eq(tuples(db, params), tuples(db2, params)));
        let c1 = |t: Tuple| if t.customer.c_custkey == g_c_custkey && t.customer.c_name == g_c_name && t.customer.c_acctbal == g_c_acctbal && t.customer.c_phone == g_c_phone && t.nation.n_name == g_n_name && t.customer.c_address == g_c_address && t.customer.c_comment == g_c_comment { f(t) } else { 0 };
        let c2 = |t: Tuple| if t.customer.c_custkey == g_c_custkey && t.customer.c_name == g_c_name && t.customer.c_acctbal == g_c_acctbal && t.customer.c_phone == g_c_phone && t.nation.n_name == g_n_name && t.customer.c_address == g_c_address && t.customer.c_comment == g_c_comment { f(t) } else { 0 };
